using DevTrack.Application; using DevTrack.Domain; using DevTrack.Infrastructure; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace DevTrack.Api.Controllers;
[Authorize] public class DashboardController(DevTrackDbContext db):ApiControllerBase
{
 [HttpGet] public async Task<DashboardDto> Get(){var today=DateOnly.FromDateTime(DateTime.UtcNow);var start=today.AddDays(-((int)today.DayOfWeek+6)%7);var all=await db.LearningTasks.AsNoTracking().Where(x=>x.UserId==UserId).ToListAsync();List<TaskDto> M(IEnumerable<LearningTask>x)=>x.Select(t=>t.ToDto(today)).ToList();var completed=all.Where(x=>x.Status==LearningTaskStatus.Completed).ToList();var dates=completed.Where(x=>x.CompletedAtUtc!=null).Select(x=>DateOnly.FromDateTime(x.CompletedAtUtc!.Value)).Distinct().ToHashSet();int streak=0;var cursor=dates.Contains(today)?today:today.AddDays(-1);for(var d=cursor;dates.Contains(d);d=d.AddDays(-1))streak++;var overdue=all.Where(x=>x.IsOverdue(today)).ToList();var week=all.Where(x=>x.PlannedDate>=start&&x.PlannedDate<=start.AddDays(6)).ToList();var reminders=overdue.Take(3).Select(x=>$"Gecikmiş görev: {x.Title}").Concat(week.Where(x=>x.Status!=LearningTaskStatus.Completed).Take(2).Select(x=>$"Bu hafta planlandı: {x.Title}")).ToList();return new(M(all.Where(x=>x.PlannedDate==today)),M(week),M(overdue),M(completed.OrderByDescending(x=>x.CompletedAtUtc).Take(5)),M(all.Where(x=>x.Status!=LearningTaskStatus.Completed&&x.Deadline>=today).OrderBy(x=>x.Deadline).Take(5)),completed.Count,all.Count-completed.Count,Mapping.Percent(completed.Count,all.Count),streak,reminders);}
}
